const SPECIES_HELP={
 dog:{title:'개',meaning:'사람과 함께 생활하며 먹이와 건강 돌봄을 받는 포유류예요.',examples:'진돗개·푸들·말티즈 등 여러 품종이 있어요.'},
 cat:{title:'고양이',meaning:'사람과 함께 생활하며 돌봄을 받는 포유류예요.',examples:'높은 곳에 오르거나 몸을 숨길 수 있는 공간을 좋아하기도 해요.'},
 fish:{title:'어류(물고기)',meaning:'물에서 살며 지느러미로 헤엄치는 동물이에요.',examples:'금붕어·구피·열대어 등이 있어요.'},
 mammal:{title:'설치류·포유류',meaning:'설치류는 앞니가 계속 자라 단단한 것을 갉는 포유류예요. 이 조사에서는 설치류와 그 밖의 포유류를 한 항목으로 묶었어요.',examples:'햄스터·기니피그·토끼·페럿 등이 있어요.'},
 bird:{title:'조류(새)',meaning:'깃털과 날개가 있는 동물이에요.',examples:'앵무새·카나리아·문조 등이 있어요.'},
 reptile:{title:'파충류',meaning:'비늘이 있고 몸의 온도가 주변에 따라 달라지는 동물이에요.',examples:'도마뱀·거북·뱀 등이 있어요.'}
};
const initial=(role='teacher')=>({page:role==='student'?3:1,visited:role==='student'?[3]:[1],experience:'',introKeyword:'',statAnswers:{},graph:0,speciesRank:Array(6).fill(''),rankSelected:'',rankFeedback:'',lastRankIndex:-1,wrongRankIndex:-1,revealedBars:[],lastRevealedSpecies:'',graphRevealed:false,graphQuestionsReady:false,dogGuess:'',dogRevealed:false,activeCase:null,openedEnvelope:'',studentCompletedCase:'',drafts:{},records:{},synthesis:'',thought:'',thoughtDecision:null,decisionText:''});
let access=null,accessRole='',state=initial(),toastTimer,graphRevealTimer=null,rankWrongTimer=null,tryAgainTimer=null,needsSave=false,draggedSpecies='';
try{const savedAccess=JSON.parse(sessionStorage.getItem(ACCESS_STORAGE));if(savedAccess&&['teacher','student'].includes(savedAccess.role))access=savedAccess;}catch{}
const storageKey=()=>access?`${STORAGE}-${access.role}-${access.code}`:STORAGE;
function loadProfile(startAtRolePage=false){state=initial(access?.role);try{const saved=JSON.parse(localStorage.getItem(storageKey()));if(saved?.version===1&&saved.state)state={...state,...saved.state};}catch{}if(!Number.isInteger(state.page)||state.page<1||state.page>5)state.page=access?.role==='student'?3:1;if(access?.role==='student'&&state.page<3)state.page=3;if(startAtRolePage){state.page=access?.role==='student'?3:1;state.activeCase=null;}state.visited=Array.isArray(state.visited)?state.visited:[];if(!state.visited.includes(state.page))state.visited.push(state.page);state.activeCase=LESSON.cases.some(c=>c.id===state.activeCase)?state.activeCase:null;state.records=Object.fromEntries(Object.entries(state.records||{}).filter(([id])=>LESSON.cases.some(c=>c.id===id)));if(access?.role==='student'&&state.page===3&&!state.activeCase){const assignedId=STUDENT_CODE_CASES[access.code];if(assignedId&&!state.records[assignedId]){state.activeCase=assignedId;state.drafts=state.drafts||{};state.drafts[assignedId]=state.drafts[assignedId]||{evidence:[],action:'',category:''};state.drafts[assignedId].articleOpened=true;}}}
if(access)loadProfile();
const entries=()=>LESSON.cases.filter(c=>state.records[c.id]).map(c=>[c,state.records[c.id]]);
const currentCase=()=>LESSON.cases.find(c=>c.id===state.activeCase);
const draft=c=>{const d=state.drafts[c.id]||(state.drafts[c.id]={evidence:[],action:'',category:''});if(!Array.isArray(d.evidence))d.evidence=[];const validEvidence=[...c.paragraphs.join(' ').matchAll(/\[\[(.*?)\]\]/g)].map(m=>m[1]);d.evidence=d.evidence.filter(word=>validEvidence.includes(word));if(!Array.isArray(d.predictionRevealed))d.predictionRevealed=[];return d;};
const category=id=>LESSON.categories.find(c=>c.id===id);
const button=(label,action,kind='primary',disabled=false,extra='')=>`<button class="${kind}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const source=s=>`<a class="source" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(s.label)} · 외부 자료" title="외부 자료">${esc(s.label)} <span aria-hidden="true">↗</span></a>`;
function persist(){if(!access)return;try{localStorage.setItem(storageKey(),JSON.stringify({version:1,state}));}catch{if(!needsSave){needsSave=true;notify('현재 브라우저에 기록을 보관할 수 없어요. 마지막에 보고서를 저장해 주세요.');}}}
function notify(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800);}
function showTryAgain(){document.querySelector('.try-again-popup')?.remove();clearTimeout(tryAgainTimer);const popup=document.createElement('div');popup.className='try-again-popup';popup.setAttribute('role','status');popup.setAttribute('aria-live','assertive');popup.innerHTML='<span aria-hidden="true">!</span><strong>다시 생각해 보세요.</strong>';document.body.append(popup);requestAnimationFrame(()=>popup.classList.add('show'));tryAgainTimer=setTimeout(()=>{popup.classList.remove('show');setTimeout(()=>popup.remove(),180);},1400);}
function navigate(page){if(access?.role==='student'&&page<3)page=3;state.page=page;if(!state.visited.includes(page))state.visited.push(page);if(page!==3)state.activeCase=null;render();window.scrollTo({top:0,behavior:'instant'});$('app').querySelector('h1,h2')?.focus({preventScroll:true});}
function canAccess(p){if(access?.role==='teacher')return true;if(access?.role==='student'&&p<3)return false;return p<=3||(p===4?entries().length>=1:entries().length>=2&&entries().every(([,r])=>r.sentence.trim()&&r.reason.trim()));}
function accessScreen(){return `<section class="access-screen" aria-labelledby="access-title"><div class="access-copy"><span class="eyebrow">ROAD ON 사회 변화 탐정단</span><h1 id="access-title">어떻게 탐구할까요?</h1><p>역할을 고르고 선생님이 알려 준 코드를 입력하세요.</p></div><div class="access-role-grid"><button class="access-role-card ${accessRole==='teacher'?'selected':''}" data-access-role="teacher" aria-pressed="${accessRole==='teacher'}"><strong>선생님</strong><small>도입과 통계부터 수업해요</small><em>1쪽부터 시작</em></button><button class="access-role-card ${accessRole==='student'?'selected':''}" data-access-role="student" aria-pressed="${accessRole==='student'}"><strong>학생</strong><small>코드와 연결된 기사를 탐구해요</small><em>해당 기사로 바로 이동</em></button></div><form class="access-form" id="access-form" novalidate><label for="access-code">${accessRole==='teacher'?'선생님 코드':accessRole==='student'?'학생 코드 단어':'코드'}</label><div class="access-input-row"><input id="access-code" type="${accessRole==='teacher'?'password':'text'}" inputmode="text" autocomplete="off" placeholder="${accessRole==='teacher'?'선생님 코드를 입력하세요':'선생님이 알려 준 단어'}" ${accessRole?'':'disabled'} aria-describedby="access-help"><button class="primary" type="submit" ${accessRole?'':'disabled'}>탐구 시작하기 →</button></div><p id="access-help" class="access-help">${accessRole==='teacher'?'입력한 코드는 다른 사람에게 보이지 않아요.':accessRole==='student'?'띄어쓰기가 달라도 같은 코드로 인식해요.':'먼저 선생님 또는 학생을 선택하세요.'}</p><p class="access-error" id="access-error" role="alert" aria-live="polite"></p></form></section>`;}
function enterAccess(){const input=$('access-code'),error=$('access-error');if(!accessRole||!input)return;const typed=input.value.trim(),normalized=typed.replace(/\s+/g,''),caseId=STUDENT_CODE_CASES[normalized];const valid=accessRole==='teacher'?normalized===TEACHER_CODE:Boolean(caseId);if(!valid){error.textContent=accessRole==='teacher'?'선생님 코드를 다시 확인하세요.':'선생님이 알려 준 코드 단어를 다시 확인하세요.';input.classList.add('invalid');input.focus();return;}const code=accessRole==='teacher'?TEACHER_CODE:normalized;access={role:accessRole,code};sessionStorage.setItem(ACCESS_STORAGE,JSON.stringify(access));loadProfile(true);if(access.role==='student'){state.page=3;state.activeCase=caseId;const assignedCase=LESSON.cases.find(c=>c.id===caseId);if(assignedCase)draft(assignedCase).articleOpened=true;if(!state.visited.includes(3))state.visited.push(3);}render();window.scrollTo({top:0,behavior:'instant'});notify(access.role==='teacher'?'선생님 화면을 열었어요.':`‘${typed}’ 기사문 탐구를 시작해요.`);}
function switchUser(){persist();access=null;accessRole='';sessionStorage.removeItem(ACCESS_STORAGE);state=initial();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 stopVillage();
 document.body.classList.toggle('access-gate',!access);
 if(!access){$('steps').innerHTML='';$('app').innerHTML=accessScreen();$('page-label').textContent='사용자 선택';$('user-badge').hidden=true;$('switch-user').hidden=true;$('restart-page').hidden=true;$('teacher').hidden=true;return;}
 document.body.classList.toggle('statistics-page',state.page===2);
 $('steps').innerHTML=pageNames.map((name,i)=>`<button class="step ${state.page===i+1?'current':''} ${state.visited.includes(i+1)&&state.page!==i+1?'done':''} ${access.role==='student'&&i<2?'role-skipped':''}" data-page="${i+1}" ${state.page===i+1?'aria-current="step"':''} ${!canAccess(i+1)?'disabled':''}><span class="num">${i+1}</span><span class="step-label">${name}</span></button>`).join('');
 $('user-badge').textContent=access.role==='teacher'?'선생님':`학생 · ${access.code}`;$('user-badge').hidden=false;$('switch-user').hidden=false;$('restart-page').hidden=false;$('teacher').hidden=false;
 $('app').innerHTML=[intro,statistics,casesPage,recordsPage,synthesisPage][state.page-1]();
 const keywordSlip=document.querySelector('.keyword-slip');if(keywordSlip)setTimeout(()=>keywordSlip.classList.add('ready'),650);
 $('app').querySelector('h1,h2')?.setAttribute('tabindex','-1');
 if(state.page===1){updateVillage();if(typeof updateIntroKeyword==='function')updateIntroKeyword();}
 $('page-label').textContent=`${state.page} / 5 · ${pageNames[state.page-1]}`;persist();
}
