function heroArt(){return `<svg viewBox="0 0 600 510" role="img" aria-label="사람과 개, 고양이, 새, 물고기가 함께하는 생활을 표현한 그림"><path d="M65 410Q295 355 535 410" fill="none" stroke="#b8c3e8" stroke-width="12"/><path d="M305 308q-15 100 9 137h75q18-78-2-137" fill="#7b87bf"/><path d="M273 174q47-32 94-1l40 145H259z" fill="#f0bfa6"/><circle cx="321" cy="135" r="44" fill="#f4d8c4"/><path d="M278 132q-7-64 46-58 50 1 42 67l-18-38q-45 29-70 29" fill="#343e79"/><circle cx="307" cy="137" r="3" fill="#29335e"/><circle cx="337" cy="137" r="3" fill="#29335e"/><path d="M314 156q10 8 20-1" stroke="#b16b54" stroke-width="3" fill="none" stroke-linecap="round"/><path d="M274 204q-40 41-79 60" fill="none" stroke="#f4d8c4" stroke-width="25" stroke-linecap="round"/><path d="M376 209q40 42 61 81" fill="none" stroke="#f4d8c4" stroke-width="25" stroke-linecap="round"/><ellipse cx="182" cy="365" rx="70" ry="53" fill="#d99d6a"/><path d="M124 395l-5 44m99-44l8 44" stroke="#b87c51" stroke-width="20" stroke-linecap="round"/><path d="M247 354q35-20 20-46" stroke="#d99d6a" stroke-width="19" fill="none" stroke-linecap="round"/><circle cx="146" cy="300" r="45" fill="#e4b383"/><path d="M111 272q-28-2-24 39 15 32 28-1m63-38q27 2 16 47-18 20-24-2" fill="#a86e4c"/><circle cx="134" cy="295" r="4" fill="#493b34"/><circle cx="158" cy="295" r="4" fill="#493b34"/><ellipse cx="145" cy="311" rx="8" ry="6" fill="#493b34"/><path d="M117 337q30 11 58-3" stroke="#df704e" stroke-width="8" fill="none"/><ellipse cx="448" cy="394" rx="40" ry="48" fill="#f7f4f5"/><circle cx="448" cy="340" r="36" fill="#f7f4f5"/><path d="M414 324l5-36 25 26m10 0l24-26 3 39" fill="#d1d6e8"/><circle cx="435" cy="338" r="3" fill="#39405d"/><circle cx="461" cy="338" r="3" fill="#39405d"/><path d="M444 351h8l-4 5z" fill="#d78f98"/><path d="M479 417q57 14 44-24" fill="none" stroke="#f7f4f5" stroke-width="14" stroke-linecap="round"/><circle cx="455" cy="160" r="31" fill="#88bda4"/><ellipse cx="460" cy="205" rx="24" ry="31" fill="#72a98f"/><path d="M429 161l-22 11 24 7" fill="#e8a064"/><circle cx="445" cy="155" r="4" fill="#263f39"/><path d="M476 220l-6 36-20-34" fill="#538575"/><path d="M426 239h66" stroke="#899a91" stroke-width="5" stroke-linecap="round"/><path d="M90 168h105v86H90z" fill="#d9f1f7" stroke="#96adca" stroke-width="5"/><path d="M91 180h102" stroke="#6eabc0" stroke-width="4"/><ellipse cx="140" cy="209" rx="18" ry="11" fill="#e8a45e"/><path d="M158 207l17-12v27l-17-10" fill="#e8a45e"/><circle cx="132" cy="208" r="2" fill="#344765"/><circle cx="112" cy="236" r="4" fill="#91c2d0"/></svg>`;}
function introOverview(){return `<div class="intro"><div class="intro-copy"><span class="eyebrow">우리 반 사회 탐정단에게 탐구가 도착했습니다</span><h1>서로 다른 동물,<br><span>함께하는 생활</span></h1><p class="lead">${LESSON.question}</p><div class="mission-strip"><span><b>1</b> 혼자 살펴보기</span><span><b>2</b> 짝과 비교하기</span><span><b>3</b> 근거로 말하기</span></div><div class="experience"><h3>어떤 경험이 떠오르나요?</h3><div class="chips">${['함께 생활해 봤어요','주변에서 본 적 있어요','자료로 알아보고 싶어요'].map(t=>`<button class="chip ${state.experience===t?'selected':''}" data-experience="${esc(t)}" aria-pressed="${state.experience===t}">${t}</button>`).join('')}</div><p class="micro" style="margin-top:12px">반려동물과 살아 본 경험이 없어도 자료를 보고 탐구할 수 있어요.</p></div><div class="actions"><div>${button('탐구 시작하기 →','start')}</div></div></div><div class="hero-art"><span class="art-tag">우리 사회의 다양한 생활을 발견해요</span>${heroArt()}</div></div><p class="note">오늘은 자료 속 사람들이 무엇을 하는지 살펴봅니다. 함께 살아갈 때의 좋은 점과 어려움은 다음 시간에 더 알아봐요.</p>`;}
function speciesInfo(id){return SPECIES_ORDER.find(s=>s[0]===id);}
function rankAnswers(){if(!Array.isArray(state.speciesRank)||state.speciesRank.length!==SPECIES_ORDER.length)state.speciesRank=Array(SPECIES_ORDER.length).fill('');return state.speciesRank;}
function rankComplete(){return rankAnswers().every((id,i)=>id===SPECIES_ORDER[i][0]);}
function successTone(){try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;const ctx=successTone.ctx||(successTone.ctx=new AudioContext());ctx.resume();const now=ctx.currentTime;[[880,now,.11],[1174,now+.1,.16]].forEach(([frequency,start,duration])=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.16,start+.018);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain).connect(ctx.destination);osc.start(start);osc.stop(start+duration+.02);});}catch{}}
function placeSpecies(id,rankIndex){const slots=rankAnswers(),expected=SPECIES_ORDER[rankIndex]?.[0];if(!expected||slots.includes(id))return;if(id!==expected){clearTimeout(rankWrongTimer);state.wrongRankIndex=rankIndex;state.rankFeedback='';state.rankSelected=id;persist();render();showTryAgain();rankWrongTimer=setTimeout(()=>{state.wrongRankIndex=-1;document.querySelector(`[data-rank-slot="${rankIndex}"]`)?.classList.remove('wrong-pulse');persist();},900);return;}clearTimeout(rankWrongTimer);state.wrongRankIndex=-1;slots[rankIndex]=id;state.rankSelected='';state.rankFeedback=`${rankIndex+1}위를 찾았어요!`;state.lastRankIndex=rankIndex;persist();render();successTone();}
function chooseDogGuess(value){state.dogGuess=value;if(value==='80'){state.dogRevealed=true;successTone();}else state.dogRevealed=false;persist();render();}
function revealedBarIds(){if(!Array.isArray(state.revealedBars))state.revealedBars=[];return state.revealedBars;}
function revealSpeciesBar(id){if(!rankComplete()||revealedBarIds().includes(id)||!SPECIES_VALUES.hasOwnProperty(id))return;clearTimeout(graphRevealTimer);state.revealedBars=[...revealedBarIds(),id];state.lastRevealedSpecies=id;state.graphRevealed=true;state.graphQuestionsReady=false;persist();render();successTone();if(state.revealedBars.length===SPECIES_ORDER.length){graphRevealTimer=setTimeout(()=>{graphRevealTimer=null;state.lastRevealedSpecies='';state.graphQuestionsReady=true;persist();if(state.page===2)render();successTone();},1050);}}
function speciesGraphPanel(){const slots=rankAnswers(),filled=slots.filter(Boolean).length,rankReady=rankComplete(),revealedSet=new Set(revealedBarIds()),barsComplete=revealedSet.size===SPECIES_ORDER.length;const title=barsComplete?'실제 조사 그래프를 완성했어요!':rankReady?'동물을 눌러 막대를 하나씩 확인해요':'순위를 생각하며 빈 그래프를 살펴봐요';return `<section class="panel species-graph-panel"><div class="graph-panel-head"><div><span class="eyebrow">반려동물 종류 그래프</span><h3>${title}</h3></div><span class="rank-progress">${rankReady?`${revealedSet.size} / 6 막대`:`${filled} / 6`}</span></div><p class="rank-guide">${barsComplete?'막대의 높이와 숫자를 함께 살펴보세요.':rankReady?'오른쪽에서 동물을 하나씩 누르며 예상과 비교해 보세요.':'지금은 그래프의 틀만 보고 결과를 예상해 보세요.'}</p><div class="species-chart" role="img" aria-label="${barsComplete?'반려동물 종류별 실제 조사 결과 막대그래프':`실제 높이를 ${revealedSet.size}개 확인한 막대그래프`}"><div class="chart-y-axis"><span>100</span><span>80</span><span>60</span><span>40</span><span>20</span><span>0</span></div><div class="species-plot"><div class="chart-grid-lines" aria-hidden="true">${Array.from({length:6},()=>'<i></i>').join('')}</div><div class="species-bars">${SPECIES_ORDER.map(species=>{const [id,name,icon]=species,value=SPECIES_VALUES[id],revealed=revealedSet.has(id);return `<div class="species-bar-cell ${revealed?'filled':''} ${state.lastRevealedSpecies===id?'revealing':''}">${revealed?`<div class="species-bar-fill" style="--bar:${value}%;--delay:0s"><span class="bar-value">${value}</span></div>`:'<div class="empty-bar"><span>?</span></div>'}</div>`;}).join('')}</div></div><div></div><div class="chart-x-labels">${SPECIES_ORDER.map(([id,name,icon,chartName],i)=>`<div class="${rankReady?'revealed':''}"><span aria-hidden="true">${rankReady?icon:'?'}</span><b>${rankReady?chartName:`${i+1}위`}</b></div>`).join('')}</div></div><div class="graph-caption"><p class="graph-unit">반려동물을 기르는 가구 100가구를 기준으로 나타낸 모습 · 중복응답</p><p class="graph-source"><strong>조사 연도: 2025년</strong><span>출처: 농림축산식품부, 「2025년 반려동물 양육현황조사」</span><a href="${LESSON.statistics.source}" target="_blank" rel="noopener noreferrer">원문 보기 ↗</a></p></div></section>`;}
function rankingSidePanel(){const slots=rankAnswers(),placed=new Set(slots.filter(Boolean));return `<aside class="panel graph-side-panel ranking-stage"><div class="activity-title"><span class="eyebrow">순위 예상하기</span><span class="rank-progress">${placed.size} / 6</span></div><div class="species-bank compact-bank" aria-label="순위를 기다리는 동물 카드">${SPECIES_BANK.filter(id=>!placed.has(id)).map(id=>{const [,name,icon]=speciesInfo(id);return `<button class="species-card ${state.rankSelected===id?'selected':''}" draggable="true" data-species-choice="${id}" aria-pressed="${state.rankSelected===id}"><span aria-hidden="true">${icon}</span>${name}</button>`;}).join('')}</div><div class="rank-list" aria-label="반려동물 종류 예상 순위">${SPECIES_ORDER.map((species,i)=>{const id=slots[i],placedSpecies=id?speciesInfo(id):null;return `<button class="rank-slot ${id?'correct':''} ${state.wrongRankIndex===i?'wrong-pulse':''}" data-rank-slot="${i}" ${id?'disabled':''}><b>${i+1}위</b>${placedSpecies?`<span aria-hidden="true">${placedSpecies[2]}</span><strong>${placedSpecies[1]}</strong><em>✓</em>`:'<span class="drop-hint">동물 카드 놓기</span>'}</button>`;}).join('')}</div><p class="rank-feedback ok" aria-live="polite">${state.rankFeedback||'정답 자리는 초록색으로 바뀌고 소리가 나요.'}</p></aside>`;}
function graphRevealPanel(){const revealed=new Set(revealedBarIds()),complete=revealed.size===SPECIES_ORDER.length;return `<aside class="panel graph-side-panel reveal-stage"><span class="eyebrow">막대 높이 확인하기</span><h3>${complete?'그래프를 모두 완성했어요!':'어떤 동물부터 확인할까요?'}</h3><p class="bar-reveal-guide">누르기 전에 막대 높이를 먼저 예상해 보세요.</p><div class="bar-reveal-buttons">${SPECIES_ORDER.map(([id,name,icon])=>`<button class="bar-reveal-choice ${revealed.has(id)?'revealed':''}" data-reveal-bar="${id}" ${revealed.has(id)?'disabled':''}><span aria-hidden="true">${icon}</span><strong>${name}</strong><em>${revealed.has(id)?'확인 ✓':'눌러 보기'}</em></button>`).join('')}</div>${complete?'<p class="pair-talk graph-ready-message">완성된 그래프를 잠깐 살펴보세요. 곧 문제가 나타나요.</p>':'<p class="pair-talk">동물을 하나씩 누르며 예상과 실제 높이를 비교하세요.</p>'}</aside>`;}
function graphQuestionPanel(){const allCorrect=GRAPH_QUESTIONS.every(q=>state.statAnswers[q.id]===q.correct);return `<aside class="panel graph-side-panel question-stage"><div class="activity-title"><div><span class="eyebrow">그래프 읽기</span><h3>완성한 그래프에서 찾아요</h3></div>${allCorrect?'<span class="question-complete">완료 ✓</span>':''}</div><div class="graph-questions">${GRAPH_QUESTIONS.map((q,i)=>{const answer=state.statAnswers[q.id];return `<section class="graph-question"><h4>${i+1}. ${q.text}</h4><div class="graph-answer-row">${q.choices.map(([id,label])=>`<button class="answer ${answer===id?(id===q.correct?'correct':'wrong'):''}" data-stat="${q.id}" data-choice="${id}" aria-pressed="${answer===id}">${label}</button>`).join('')}</div>${answer?`<p class="feedback ${answer===q.correct?'ok':'error'}">${answer===q.correct?'그래프에서 잘 찾았어요.':'다시 생각해 보세요. 왼쪽 그래프를 살펴보세요.'}</p>`:''}</section>`;}).join('')}</div></aside>`;}
function speciesGlossary(){return `<section class="species-glossary" aria-labelledby="species-glossary-title"><div class="glossary-heading"><span aria-hidden="true">📖</span><div><h3 id="species-glossary-title">그래프 속 낱말 사전</h3><p>괄호 안은 쉬운 말이나 예시 동물이에요. 조사에서는 설치류와 그 밖의 포유류를 한 항목으로 묶었어요.</p></div></div><div class="glossary-list">${SPECIES_GLOSSARY.map(([term,meaning,examples])=>`<div class="glossary-item"><b>${term}</b><span>${meaning}</span><em>예: ${examples}</em></div>`).join('')}</div></section>`;}
function statistics(){const rankReady=rankComplete(),barsComplete=revealedBarIds().length===SPECIES_ORDER.length,complete=state.graphQuestionsReady&&GRAPH_QUESTIONS.every(q=>state.statAnswers[q.id]===q.correct);const side=!rankReady?rankingSidePanel():!barsComplete||!state.graphQuestionsReady?graphRevealPanel():graphQuestionPanel();return `${header('02 · 그래프를 완성하고 읽기','어떤 반려동물과 함께 살까요?','순위를 예상하고 막대 높이를 충분히 생각한 뒤, 실제 그래프에서 답을 찾아보세요.')}<div class="graph-investigation-layout">${speciesGraphPanel()}${side}</div>${speciesGlossary()}<div class="stat-source-row"><p><strong>자료를 보고 알 수 있는 점</strong> · 개가 가장 많지만 고양이, 물고기, 새, 파충류 등 여러 동물과 함께 생활해요.</p><div class="stat-source-actions">${source({label:'통계 원문',url:LESSON.statistics.source})}${button('← 탐구 시작','back','secondary')}${button('생활 모습 탐사 →','to-cases','primary',!complete)}</div></div>`;}
function studentTransitionPage(){
 const completed=LESSON.cases.find(c=>c.id===state.studentCompletedCase),index=LESSON.cases.findIndex(c=>c.id===state.studentCompletedCase),next=LESSON.cases[index+1];
 if(!completed)return `<section class="panel student-transition"><span class="eyebrow">학생 탐사</span><h2>선생님이 알려 준 기사 코드로 시작해요.</h2><p>사용자 바꾸기를 누르고 학생 코드를 입력해 주세요.</p></section>`;
 if(!next){const allDone=entries().length===LESSON.cases.length;return `${header('탐사 완료',allDone?'세 가지 기사문 탐구를 마쳤어요!':'이번 기사문 탐구를 마쳤어요!','모은 증거와 발견 기록을 살펴보세요.')}<section class="panel student-transition"><strong>${allDone?'탐사 01 · 탐사 02 · 탐사 03 완료':`${esc(completed.title)} 탐사 완료`}</strong>${button('발견 기록 살펴보기 →','to-records','primary')}</section>`;}
 return `${header(`탐사 ${completed.number} 완료`,'다음 탐사로 넘어가시겠습니까?','선생님이 다음 기사 키워드를 알려 주면 코드를 입력해 이동하세요.')}<section class="panel student-transition"><div class="transition-check">✓</div><h3>${esc(completed.title)} 탐사를 기록했어요.</h3><p>다음 사건은 코드가 있어야 열 수 있어요.</p>${button('다음 탐사 코드 입력하기 →','ask-next-case','primary')}</section>`;
}
function casesPage(){if(currentCase())return caseDetail(currentCase());if(access?.role==='student')return studentTransitionPage();return `${header('03 · 사건 봉투 열기','어떤 생활 모습을 탐사할까요?','봉투를 하나 골라 누르면 기사 키워드가 나타나요.',`<span class="record-count">발견 기록 ${entries().length} / ${LESSON.cases.length}</span>`)}<div class="case-envelope-grid">${LESSON.cases.map(c=>{const opened=state.openedEnvelope===c.id,saved=Boolean(state.records[c.id]);return `<article class="case-envelope-item ${opened?'opened':''}"><button class="envelope-trigger ${opened?'open':''}" data-envelope="${c.id}" aria-expanded="${opened}" aria-label="탐사 ${c.number} 사건 봉투 ${opened?'열림':'열기'}"><span class="case-number">탐사 ${c.number}</span><span class="envelope-visual" aria-hidden="true"><i class="envelope-paper"></i><i class="envelope-front"></i><i class="envelope-flap"></i><b>${saved?'✓':'?'}</b></span><span class="envelope-hint">${saved?'기록한 사건 · 다시 열기':opened?'키워드를 확인했어요':'봉투를 눌러 열어 보세요'}</span></button>${opened?`<div class="keyword-slip"><small>기사 키워드</small><strong>${esc(c.keyword)}</strong><div class="keyword-slip-actions"><button class="secondary" data-predict-case="${c.id}">기사 예상하기</button><button class="primary" data-direct-case="${c.id}">기사문 탐구하기</button></div></div>`:''}</article>`;}).join('')}</div><p class="envelope-focus-note">한 번에 한 봉투만 열려요. 키워드를 보고 예상 활동을 할지 기사문을 바로 읽을지 선택하세요.</p><div class="actions">${button('← 통계 탐구','back','secondary')}<div><span class="micro">2개 이상 탐사하면 생각을 모을 수 있어요.</span>${button('발견 기록 살펴보기 →','to-records','primary',entries().length<1)}</div></div>`;}
function casePrediction(c,d){const predictionReady=d.predictionRevealed.length>0;return `${header(`탐사 ${c.number} · 기사 예상하기`,c.keyword,'키워드를 보고 단서를 하나씩 열어 보세요.',button('자료 목록','case-list','secondary'))}<div class="prediction-layout case-prediction-layout teacher-prediction-layout"><section class="panel keyword-stage"><span class="eyebrow">기사 속 키워드</span><strong>${esc(c.keyword)}</strong><p>${esc(c.predictionQuestion)}</p></section><aside class="panel prediction-panel"><div class="clue-panel-heading"><span class="eyebrow">단서 카드</span></div><div class="prediction-clue-cards">${c.clueKeywords.map((keyword,i)=>{const id=`clue-${i}`;return d.predictionRevealed.includes(id)?`<div class="prediction-clue-card opened"><span>단서 ${i+1}</span><strong>${esc(keyword)}</strong></div>`:`<button class="prediction-clue-card closed" data-reveal-prediction="${id}"><span>단서 ${i+1}</span><strong>눌러서 열기</strong></button>`;}).join('')}</div>${button('기사문 탐구하기 →','open-article','primary',!predictionReady,'style="width:100%"')}</aside></div>`;}
function educationPoster(c){return `<figure class="education-poster-card" role="img" aria-label="${esc(c.imageAlt)}"><div class="poster-top"><span>부산광역시</span><b>반려동물 돌봄 시민교육</b></div><h3>보호자도 함께 배워요!</h3><div class="poster-lessons"><span>행동 이해</span><span>사회화·예절</span><span>양육·기본 관리</span></div><p>장소 · 신라대학교</p><figcaption>부산시 교육 포스터의 핵심 내용을 어린이용으로 재구성</figcaption></figure>`;}
function evidenceButton(c,d,word){const cue=c.evidenceCues?.[word]||'중요 단어';return `<button class="evidence-word ${d.evidence.includes(word)?'marked':''}" data-evidence="${esc(word)}" aria-pressed="${d.evidence.includes(word)}"><small>${esc(cue)}</small><span>${word}</span></button>`;}
function caseDetail(c){
 const d=draft(c);if(!d.articleOpened)return casePrediction(c,d);
 const actionOK=d.action===c.correctAction,classified=d.category===c.category,evidenceReady=d.evidence.length>=3,ready=actionOK&&classified&&evidenceReady;
 const side=access?.role==='teacher'?button('자료 목록','case-list','secondary'):'';
 return `${header(`탐사 ${c.number} · ${c.animal}`,c.title,access?.role==='student'?'기사에서 사람들의 행동과 그 근거를 찾아보세요.':'예상한 내용과 기사를 비교하고, 사람들의 행동을 찾아보세요.',side)}
 <div class="case-workspace">
  <article class="panel case-story">
   <div class="article-top"><span>ROAD ON 어린이 생활 신문</span><span>${c.place} · ${c.date}</span></div>
   <h2>${c.articleTitle}</h2>
   <p class="evidence-guide"><strong>중요 단어 수집</strong> · 누가, 어디서, 무엇을, 어떻게 했는지 보여 주는 밑줄 단어를 눌러 보세요.</p>
   <div class="article-body">${c.paragraphs.map(p=>`<p>${esc(p).replace(/\[\[(.*?)\]\]/g,(_,word)=>evidenceButton(c,d,word))}</p>`).join('')}</div>
   ${c.image?`<figure class="media-figure"><img src="${c.image}" alt="${esc(c.imageAlt)}"><figcaption>${c.imageCaption}</figcaption></figure>`:educationPoster(c)}
   <div class="process" aria-label="자료에서 확인한 활동 과정">${c.process.map((p,i)=>`<div><b>${i+1}</b>${p}</div>`).join('')}</div>
   <p class="note">${c.note}</p><div class="source-list">${c.sources.map(source).join('')}</div>
   <p class="micro">출처: ${c.sources.map(s=>s.publisher).join(' / ')} · 어린이용 재구성<br>원문은 외부 사이트에서 열려요. 외부 페이지에는 광고 등이 있을 수 있어요.</p>
  </article>
  <aside class="panel inquiry-panel">
   ${!d.questionsOpened?`<section class="reading-side-panel"><span class="eyebrow">기사문 먼저 읽기</span><h3>어려운 낱말을 확인해요</h3><p class="micro">낱말을 누르면 뜻을 볼 수 있어요. 기사 속 밑줄 단어도 눌러 읽어 보세요.</p><div class="side-glossary" aria-label="낱말 풀이">${c.glossary.map(([w,m])=>`<details><summary>${w}</summary><p>${m}</p></details>`).join('')}</div><div class="reading-progress"><strong>중요 단어 ${d.evidence.length}개 확인</strong><span>${evidenceReady?'질문을 풀 준비가 되었어요.':'기사에서 중요한 단어를 3개 이상 눌러 보세요.'}</span></div>${button('기사문을 다 읽었어요 → 질문 풀기','open-inquiry','primary',!evidenceReady,'style="width:100%"')}</section>`:`<section class="inquiry-step inquiry-return"><button class="quiet" data-action="back-to-reading">← 기사와 낱말 다시 보기</button></section><section class="inquiry-step">
    <h3>1. 누가 무엇을 하고 있나요?</h3>
    <p class="micro">비슷해 보여도 장소·방법·행동이 조금씩 달라요. 기사와 정확히 같은 것을 고르세요.</p>
    <div class="answers numbered-answers">${c.actions.map((a,i)=>`<button class="answer ${d.action===a.id?(a.id===c.correctAction?'correct':'wrong'):''}" data-observation="${a.id}" aria-pressed="${d.action===a.id}"><b>${i+1}</b><span>${a.text}</span></button>`).join('')}</div>
    ${d.action?`<p class="feedback ${actionOK?'ok':'error'}">${actionOK?'기사의 내용을 정확히 찾았어요.':'다시 생각해 보세요. 장소와 행동 방법까지 기사와 같은지 살펴보세요.'}</p>`:''}
   </section>
   <section class="inquiry-step">
    <div class="evidence-question-head"><h3>2. 육하원칙에 따라 중요한 단어를 모아요</h3><span>${d.evidence.length}개 수집</span></div>
    <p class="micro">기사의 밑줄 단어에서 서로 다른 단서를 3개 이상 찾아보세요.</p>
    <div class="evidence-tray cue-tray" style="margin-top:12px">${d.evidence.length?d.evidence.map(w=>`<span class="evidence-tag"><small>${esc(c.evidenceCues?.[w]||'단서')}</small>${esc(w)}</span>`).join(''):'<span class="micro">아직 모은 중요 단어가 없어요.</span>'}</div>
    ${d.evidence.length&&!evidenceReady?'<p class="feedback error">서로 다른 단서를 조금 더 찾아보세요.</p>':evidenceReady?'<p class="feedback ok">누가·어디서·무엇을·어떻게에 관한 단서를 모았어요.</p>':''}
   </section>
   <section class="inquiry-step">
    <h3>3. 이 기사문을 잘 나타낼 수 있는 단어는 무엇인가요?</h3>
    ${evidenceReady?`<div class="chips theme-word-choices">${LESSON.categories.map(cat=>`<button class="chip ${d.category===cat.id?(classified?'selected':'wrong'):''}" data-category="${cat.id}" aria-pressed="${d.category===cat.id}">${cat.label}</button>`).join('')}</div>
    ${d.category?`<p class="feedback ${classified?'ok':'error'}">${classified?'기사의 중심 내용을 잘 나타내는 단어예요.':'다시 생각해 보세요. 모은 중요 단어와 사람들의 행동을 함께 살펴보세요.'}</p>`:''}
    ${classified?`<button class="quiet optional-reason-button" data-action="open-theme-reason">${d.categoryReason?'선택한 까닭 고치기':'선택한 까닭 적기(선택)'}</button>`:''}
    ${d.categoryReason?`<div class="theme-reason"><strong>내가 그렇게 생각한 까닭</strong><p>${esc(d.categoryReason)}</p></div>`:''}`:'<div class="locked">중요 단어를 3개 이상 모으면 선택할 수 있어요.</div>'}
   </section>
   <section class="inquiry-step"><h3>짝과 생각을 비교해요</h3><p class="micro">“나는 이 단어와 문장을 보고 이렇게 생각했어.”<br>짝은 어떤 증거를 찾았나요?</p></section>
   ${button(state.records[c.id]?'발견 기록 고치기 ✓':'발견 기록에 담기 →','save-case','primary',!ready,'style="width:100%"')}
   <p class="micro" style="margin-top:12px">행동·중요 단어·중심 단어를 완성하면 기록할 수 있어요. 선택한 까닭은 쓰고 싶을 때만 적어도 됩니다.</p>`}
  </aside>
 </div>`;
}
function recordsPage(){const records=entries();return `${header('03 · 증거를 들어 설명하기','우리의 발견 기록','자료에서 발견한 사람들의 행동을 나의 말로 설명해 보세요.',`<span class="record-count">${records.length}개 자료 탐사 완료</span>`)}${records.length?records.map(([c,r])=>`<section class="panel record-card"><div class="record-title"><h3><span class="case-number">${c.number}</span> ${c.title}</h3><button class="chip" data-case="${c.id}">자료 다시 보기 ↗</button></div><blockquote><strong>내가 찾은 증거</strong><br>${r.evidence.map(esc).join(' · ')}</blockquote><div class="record-fields"><div class="field"><label for="action-${c.id}">사람들은 반려동물과 무엇을 하나요?</label><textarea id="action-${c.id}" data-record="${c.id}" data-field="sentence" maxlength="220">${esc(r.sentence)}</textarea></div><div class="field"><label for="reason-${c.id}">어떤 문장이나 사진을 보고 알았나요?</label><textarea id="reason-${c.id}" data-record="${c.id}" data-field="reason" maxlength="220">${esc(r.reason)}</textarea></div></div><p class="micro" style="margin-top:12px">발견한 생활 모습: ${category(r.category)?.label||''} · 짝의 생각과 비교하며 고쳐도 좋아요.</p></section>`).join(''):'<div class="panel empty"><h3>아직 발견 기록이 없어요.</h3><p>생활 모습 탐사에서 자료를 골라 보세요.</p></div>'}<div class="actions">${button('← 다른 자료도 탐사하기','to-cases','secondary')}<div><span class="micro">${records.length<2?'자료를 하나 탐사해 발견한 모습을 설명해 보세요.':'서로 다른 자료의 공통점을 찾아볼까요?'}</span>${button('생각 모으기 →','to-synthesis','primary',records.length<2||!records.every(([,r])=>r.sentence.trim()&&r.reason.trim()),'id="to-synthesis"')}</div></div>`;}
function reportMarkup(){return `<section class="report" aria-label="탐정 보고서"><div class="report-title"><div><span class="eyebrow">ROAD ON 사회 변화 탐정단</span><h2>탐정 보고서</h2></div><small>생활 문화<br>발견 완료</small></div><div class="report-section"><h3>통계에서 발견했어요</h3><p>10가구 중 약 3가구가 반려동물과 함께 살아요. 개가 가장 많지만, 고양이·물고기·새 등 여러 동물과 생활해요.</p></div>${entries().map(([c,r])=>`<div class="report-record"><h3>${c.title} · ${category(r.category)?.label||''}</h3><p>${esc(r.sentence)}</p><p class="micro">${esc(r.reason)}</p></div>`).join('')}<div class="report-section"><h3>여러 자료의 공통점</h3><p>사람들은 반려동물을 돌보고 교감하며, 함께 활동하면서 살아갑니다. 이런 생활은 물건·서비스·장소·행사에서 찾아볼 수 있습니다.</p></div><div class="field final-field"><label for="final-thought">나의 한 줄 생각</label><textarea id="final-thought" maxlength="300" placeholder="자료를 보고 새롭게 알게 된 생활 모습을 적어 보세요.">${esc(state.thought)}</textarea><p class="micro">Enter를 누르거나 입력칸을 벗어나면 이미지 저장 여부를 물어요.</p></div><div class="actions"><div>${button('PNG 이미지로 저장','save-report','secondary')}</div></div><p class="micro" style="margin-top:15px">통계: 농림축산식품부, 2025년 반려동물 양육현황조사<br>사례별 원문 출처는 저장되는 보고서에도 함께 기록됩니다.</p></section>`;}
function synthesisPage(){const q=LESSON.synthesis,ok=state.synthesis===q.correct;return `${header('04 · 여러 생활 모습 연결하기','다르지만, 함께 살아가는 모습','시설 이름보다 사람들의 생활을 중심으로 이야기해 보세요.')}<div class="synthesis"><div><section class="panel synthesis-question"><h2 style="font-size:29px">${q.question}</h2><div class="answers">${q.choices.map(c=>`<button class="answer ${state.synthesis===c.id?(ok?'correct':'wrong'):''}" data-synthesis="${c.id}" aria-pressed="${state.synthesis===c.id}">${c.text}</button>`).join('')}</div>${state.synthesis?`<p class="feedback ${ok?'ok':'error'}">${ok?'여러 자료의 공통점을 찾았어요.':'다시 생각해 보세요. 사람들의 행동과 동물마다 다른 특성을 함께 떠올려 보세요.'}</p>`:''}<p class="note">반려동물과 함께하는 <strong>생활이 문화</strong>예요. 물건과 시설은 그 생활을 보여 주는 자료입니다.</p></section>${ok&&state.thoughtDecision!==null?extension():''}</div><div>${ok?reportMarkup():`<div class="panel empty"><h3>자료를 하나로 연결해 볼까요?</h3><p>공통점을 찾으면 우리가 모은 증거와 발견 기록이 보고서로 정리됩니다.</p></div>`}</div></div><div class="actions">${button('← 발견 기록 고치기','back','secondary')}</div>`;}
function extension(){return `<section class="extension" id="extension"><span class="eyebrow">확장 탐구</span><h3>또 다른 반려동물 생활을 찾아볼까요?</h3><p class="micro">궁금한 단어로 원문 자료를 다시 살펴보세요.</p><div class="chips">${LESSON.cases.flatMap(c=>c.sources).map(s=>`<a class="chip" href="${s.url}" target="_blank" rel="noopener noreferrer" aria-label="${esc(s.label)} 외부 기사">${s.label} ↗</a>`).join('')}</div><p class="next-lesson"><strong>다음 시간에는</strong><br>반려동물과 함께 살면 어떤 좋은 점과 어려움이 있을까요? 함께 살아가려면 어떤 노력이 필요할까요?</p></section>`;}
function showDialog(title,body,kind=''){const dialog=$('dialog');dialog.className=kind;$('dialog-content').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;dialog.showModal();dialog.querySelector('button')?.focus();}
function thoughtFinished(){const thought=state.thought.trim();if(!thought||state.synthesis!==LESSON.synthesis.correct||$('dialog').open||state.decisionText===thought)return;showDialog('보고서 이미지로 저장할까요?',`<p>나의 한 줄 생각을 탐정 보고서 이미지로 저장하시겠습니까?</p><p class="hint">${esc(thought)}</p><div class="actions">${button('저장하지 않고 계속','skip-save','secondary')}${button('이미지로 저장','confirm-save')}</div>`);}
function chooseSave(save){state.thoughtDecision=save;state.decisionText=state.thought.trim();$('dialog').close();if(save)saveReport();render();$('extension')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function celebrate(){const box=document.createElement('div');box.className='celebration';box.setAttribute('role','status');box.innerHTML=`<div><strong>생활 문화 발견 완료!</strong><p>서로 다른 자료에서 공통점을 찾았어요.</p></div>${Array.from({length:16},(_,i)=>`<i class="petal" style="--x:${4+i*6}%;--delay:${i%4*.09}s;--color:${['#d595aa','#8b9bd0','#dca778','#90b4a1'][i%4]}"></i>`).join('')}`;document.body.append(box);setTimeout(()=>box.remove(),2100);}
function teacher(){showDialog('오늘의 탐구 안내',`<div class="teacher-copy"><p><strong>대상</strong> 초등학교 3학년 · 우리 사회의 다양한 문화</p><p><strong>목표</strong> ${LESSON.goal}</p><p><strong>활동</strong> 도입 기사와 통계 → 3개 자료 중 선택 탐사 → 발견 기록 → 공통점과 보고서. 2개 이상 기록하면 생각 모으기가 열립니다.</p><p><strong>자료 읽기</strong> 종류별 그래프는 반려동물을 기르는 가구를 대상으로 한 중복응답 자료입니다.</p><p><strong>통계 출처</strong> 농림축산식품부 「2025년 반려동물 양육현황조사」 · 보도자료 발표 2026. 2. 12.</p>${source({label:'농림축산식품부 원문',url:LESSON.statistics.source})}<p><strong>수업 초점</strong> 돌봄을 맡기고, 함께 놀고, 보호자가 배우는 현재의 생활 모습을 자료에서 찾습니다.</p><p><strong>기록</strong> 이름 없이 이 브라우저에 보관합니다. 공유 기기에서는 새 수업 전에 초기화할 수 있습니다.</p><details><summary>사례별 원문 자료</summary>${LESSON.cases.map(c=>`<p><b>${c.title}</b><br>${c.sources.map(s=>`${source(s)} <small>${s.publisher}</small>`).join('<br>')}</p>`).join('')}</details></div><div class="actions">${button('기록 초기화','ask-reset','secondary')}${button('수업으로 돌아가기','close')}</div>`);}
function showSpeciesHelp(id){const info=SPECIES_HELP[id],species=speciesInfo(id);if(!info||!species)return;showDialog(info.title,`<button class="dialog-close-x" data-action="close" aria-label="팝업 닫기">×</button><div class="species-help"><span class="species-help-icon" aria-hidden="true">${species[2]}</span><p class="species-help-meaning">${info.meaning}</p><p class="species-help-examples"><strong>예를 들면</strong> ${info.examples}</p></div><div class="species-help-actions">${button('닫기','close','secondary')}<button class="primary" data-species-select="${id}">이 카드 선택하기</button></div>`,'species-help-dialog');}
function showThemeReason(c,categoryId){const selected=category(categoryId);if(!selected)return;const prior=draft(c).categoryReason||'';showDialog('선택한 까닭 적기(선택)',`<div class="theme-reason-dialog"><p><strong>내가 고른 단어</strong><span>${esc(selected.label)}</span></p><label for="theme-reason-input">쓰고 싶다면 기사에서 찾은 중요 단어를 근거로 까닭을 적어 보세요.</label><textarea id="theme-reason-input" maxlength="180" placeholder="예: 보호자가 반려동물을 더 잘 돌보기 위해 배우고 있기 때문입니다.">${esc(prior)}</textarea></div><div class="actions">${button('쓰지 않고 닫기','close','secondary')}${button('생각 저장하기','save-theme-reason')}</div>`,'theme-reason-dialog');setTimeout(()=>$('theme-reason-input')?.focus(),0);}
function showNextCaseDialog(){const index=LESSON.cases.findIndex(c=>c.id===state.studentCompletedCase),next=LESSON.cases[index+1];if(!next)return;showDialog('다음 탐사 코드 입력',`<form id="next-case-form" class="next-case-form" novalidate><p><strong>탐사 ${next.number}</strong>를 열려면 선생님이 알려 준 키워드를 입력하세요.</p><label for="next-case-code">다음 기사 코드</label><div class="access-input-row"><input id="next-case-code" autocomplete="off" placeholder="키워드 입력"><button class="primary" type="submit">다음 탐사 열기 →</button></div><p class="access-error" id="next-case-error" role="alert"></p></form><div class="actions">${button('아직 넘어가지 않기','close','secondary')}</div>`,'next-case-dialog');setTimeout(()=>$('next-case-code')?.focus(),0);}
function enterNextCase(){const input=$('next-case-code'),error=$('next-case-error');if(!input||!error)return;const normalized=input.value.trim().replace(/\s+/g,''),caseId=STUDENT_CODE_CASES[normalized],index=LESSON.cases.findIndex(c=>c.id===state.studentCompletedCase),expected=LESSON.cases[index+1];if(!expected||caseId!==expected.id){error.textContent='다음 탐사의 키워드를 다시 확인하세요.';input.classList.add('invalid');input.focus();return;}access.code=normalized;sessionStorage.setItem(ACCESS_STORAGE,JSON.stringify(access));state.activeCase=caseId;state.studentCompletedCase='';const assigned=LESSON.cases.find(c=>c.id===caseId);if(assigned)draft(assigned).articleOpened=true;$('dialog').close();render();window.scrollTo({top:0,behavior:'instant'});notify(`‘${input.value.trim()}’ 기사문 탐구를 시작해요.`);}
function restartCurrentPage(){
 clearTimeout(graphRevealTimer);graphRevealTimer=null;
 if(state.page===1){if(typeof resetMotivation==='function')resetMotivation();state.experience='';state.introKeyword='';}
 if(state.page===2){Object.assign(state,{statAnswers:{},graph:0,speciesRank:Array(6).fill(''),rankSelected:'',rankFeedback:'',lastRankIndex:-1,wrongRankIndex:-1,revealedBars:[],lastRevealedSpecies:'',graphRevealed:false,graphQuestionsReady:false,dogGuess:'',dogRevealed:false});}
 if(state.page===3){const c=currentCase();if(c){delete state.drafts[c.id];delete state.records[c.id];}else{state.activeCase=null;state.openedEnvelope='';}}
 if(state.page===4){for(const [c,r] of entries()){r.sentence=RECORD_SENTENCES[c.id];r.reason=`‘${r.evidence.join('’, ‘')}’을 보고 알았습니다.`;}}
 if(state.page===5){Object.assign(state,{synthesis:'',thought:'',thoughtDecision:null,decisionText:''});}
 render();window.scrollTo({top:0,behavior:'instant'});notify(`${pageNames[state.page-1]} 활동을 처음으로 돌렸어요.`);
}
function saveReport(){
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=1400;
 const blocks=[['핵심 질문',LESSON.question],['통계에서 발견했어요','2025년: 10가구 중 약 3가구가 반려동물과 함께 살아요. 개가 가장 많지만, 고양이·물고기·새 등 여러 동물과 함께 생활해요.'],...entries().flatMap(([c,r])=>[[`${c.number}. ${c.title} · ${category(r.category)?.label||''}`,r.sentence+'\n'+r.reason],['찾은 증거',r.evidence.join(' · ')]]),['여러 자료의 공통점','사람들은 반려동물을 돌보고 교감하며, 함께 활동하면서 살아갑니다. 이런 생활은 물건·서비스·장소·행사에서 찾아볼 수 있습니다.'],['나의 한 줄 생각',state.thought.trim()||'아직 작성하지 않았어요.'],['자료 출처','농림축산식품부 · 2025년 반려동물 양육현황조사\n'+LESSON.statistics.source+'\n'+entries().map(([c])=>c.sources.map(s=>s.publisher+' · '+s.label+'\n'+s.url).join('\n')).join('\n')]];
 ctx.font='28px "Malgun Gothic",sans-serif';
 const wrap=text=>{const lines=[];for(const paragraph of String(text).split('\n')){let line='';for(const ch of paragraph){if(ctx.measureText(line+ch).width>1210&&line){lines.push(line);line=ch;}else line+=ch;}lines.push(line);}return lines;};
 const laid=blocks.map(([title,text])=>({title,lines:wrap(text)}));canvas.height=260+laid.reduce((n,b)=>n+92+b.lines.length*43,0);
 ctx.fillStyle='#f3f5ff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#3746a0';ctx.fillRect(0,0,1400,180);ctx.fillStyle='#fff';ctx.font='bold 32px "Malgun Gothic",sans-serif';ctx.fillText('ROAD ON 사회 변화 탐정단',90,65);ctx.font='bold 49px "Malgun Gothic",sans-serif';ctx.fillText('반려동물 생활 문화 · 탐정 보고서',90,136);
 let y=248;for(const b of laid){ctx.fillStyle='#3746a0';ctx.font='bold 31px "Malgun Gothic",sans-serif';ctx.fillText(b.title,90,y);y+=49;ctx.fillStyle='#303956';ctx.font='28px "Malgun Gothic",sans-serif';for(const line of b.lines){ctx.fillText(line,90,y);y+=43;}y+=43;}
 const a=document.createElement('a');a.download='ROAD-ON_반려동물_생활문화_탐정보고서.png';a.href=canvas.toDataURL('image/png');a.click();notify('탐정 보고서 이미지를 저장했어요.');
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.accessRole){accessRole=b.dataset.accessRole;render();setTimeout(()=>$('access-code')?.focus(),0);return;}
 if(b.dataset.page){const p=Number(b.dataset.page);if(canAccess(p))navigate(p);return;}
 if(b.dataset.experience){state.experience=b.dataset.experience;render();return;}
 if(b.dataset.envelope){state.openedEnvelope=b.dataset.envelope;render();return;}
 if(b.dataset.predictCase){state.activeCase=b.dataset.predictCase;const selected=LESSON.cases.find(item=>item.id===state.activeCase);if(selected){const d=draft(selected);d.articleOpened=false;d.prediction='';d.predictionRevealed=[];}render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(b.dataset.directCase){state.activeCase=b.dataset.directCase;const selected=LESSON.cases.find(item=>item.id===state.activeCase);if(selected)draft(selected).articleOpened=true;render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(b.dataset.speciesChoice){showSpeciesHelp(b.dataset.speciesChoice);return;}
 if(b.dataset.speciesSelect){state.rankSelected=b.dataset.speciesSelect;state.wrongRankIndex=-1;state.rankFeedback='선택한 카드를 순위 칸에 놓아 보세요.';state.lastRankIndex=-1;$('dialog').close();render();return;}
 if(b.dataset.rankSlot!==undefined){if(state.rankSelected)placeSpecies(state.rankSelected,Number(b.dataset.rankSlot));return;}
 if(b.dataset.revealBar){revealSpeciesBar(b.dataset.revealBar);return;}
 if(b.dataset.dogGuess){chooseDogGuess(b.dataset.dogGuess);return;}
 if(b.dataset.graph){state.graph=Number(b.dataset.graph);render();return;}
 if(b.dataset.stat){const q=GRAPH_QUESTIONS.find(item=>item.id===b.dataset.stat);state.statAnswers[b.dataset.stat]=b.dataset.choice;state.lastRankIndex=-1;render();if(q&&q.correct===b.dataset.choice)successTone();return;}
 if(b.dataset.case){state.activeCase=b.dataset.case;state.page=3;if(!state.visited.includes(3))state.visited.push(3);render();window.scrollTo({top:0,behavior:'instant'});return;}
 const c=currentCase();
 if(b.dataset.revealPrediction&&c){const d=draft(c);if(!d.predictionRevealed.includes(b.dataset.revealPrediction))d.predictionRevealed.push(b.dataset.revealPrediction);render();return;}
 if(b.dataset.prediction&&c){draft(c).prediction=b.dataset.prediction;render();return;}
 if(b.dataset.evidence&&c){const d=draft(c),w=b.dataset.evidence;d.evidence=d.evidence.includes(w)?d.evidence.filter(x=>x!==w):[...d.evidence,w];if(d.evidence.length<3){d.category='';d.categoryReason='';}render();return;}
 if(b.dataset.observation&&c){draft(c).action=b.dataset.observation;render();return;}
 if(b.dataset.category&&c){const d=draft(c);d.category=b.dataset.category;d.categoryReason='';render();return;}
 if(b.dataset.synthesis){const prior=state.synthesis;state.synthesis=b.dataset.synthesis;render();if(state.synthesis===LESSON.synthesis.correct&&prior!==state.synthesis)celebrate();return;}
 switch(b.dataset.action){
 case 'start':navigate(2);break;
 case 'back':navigate(state.page-1);break;
 case 'to-cases':navigate(3);break;
 case 'open-article':if(c&&draft(c).predictionRevealed.length>0){draft(c).articleOpened=true;render();window.scrollTo({top:0,behavior:'instant'});}break;
 case 'case-list':state.activeCase=null;render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'to-records':if(entries().length)navigate(4);break;
 case 'to-synthesis':if(entries().length>=2&&entries().every(([,r])=>r.sentence.trim()&&r.reason.trim()))navigate(5);break;
 case 'save-case':{if(!c)return;const d=draft(c);if(d.action!==c.correctAction||d.category!==c.category||d.evidence.length<3)return;const prior=state.records[c.id],evidenceReason=`‘${d.evidence.join('’, ‘')}’을 보고 알았습니다.`;state.records[c.id]={evidence:[...d.evidence],category:d.category,sentence:prior?.sentence||RECORD_SENTENCES[c.id],reason:prior?.reason||d.categoryReason?.trim()||evidenceReason};if(access?.role==='student')state.studentCompletedCase=c.id;state.activeCase=null;render();window.scrollTo({top:0,behavior:'instant'});notify(access?.role==='student'?'탐사를 기록했어요. 다음 탐사는 코드로 열 수 있어요.':'발견 기록에 담았어요. 다른 자료도 살펴보세요.');break;}
 case 'enlarge-graph':showDialog('통계 그래프 크게 보기',`<img src="assets/${state.graph?'species':'ownership'}-2025.png" alt="${state.graph?'반려동물 종류별 양육 비율':'반려동물 양육 여부'} 원본 그래프"><div class="actions">${button('닫기','close','secondary')}</div>`,'graph-dialog');break;
 case 'close':$('dialog').close();break;
 case 'open-theme-reason':if(c&&draft(c).category)showThemeReason(c,draft(c).category);break;
 case 'ask-next-case':showNextCaseDialog();break;
 case 'open-inquiry':if(c&&draft(c).evidence.length>=3){draft(c).questionsOpened=true;render();window.scrollTo({top:0,behavior:'smooth'});}break;
 case 'back-to-reading':if(c){draft(c).questionsOpened=false;render();window.scrollTo({top:0,behavior:'smooth'});}break;
 case 'save-theme-reason':{if(!c)break;const value=$('theme-reason-input')?.value.trim();if(!value){notify('그렇게 생각한 까닭을 적어 보세요.');$('theme-reason-input')?.focus();break;}draft(c).categoryReason=value;$('dialog').close();render();break;}
 case 'skip-save':chooseSave(false);break;
 case 'confirm-save':chooseSave(true);break;
 case 'save-report':if($('dialog').open)break;if(!state.thought.trim()){notify('나의 한 줄 생각을 먼저 적어 보세요.');$('final-thought')?.focus();}else{state.thoughtDecision=true;state.decisionText=state.thought.trim();saveReport();render();}break;
 case 'ask-reset':showDialog('새 수업을 시작할까요?',`<p>이 브라우저에 보관한 이번 수업의 발견 기록이 초기화됩니다.</p><div class="actions">${button('돌아가기','close','secondary')}${button('초기화하고 시작','reset')}</div>`);break;
 case 'reset':state=initial(access?.role);if(typeof resetMotivation==='function')resetMotivation();$('dialog').close();render();window.scrollTo({top:0,behavior:'instant'});notify('새 탐구를 시작할 준비가 되었어요.');break;
 }
});
document.addEventListener('submit',e=>{if(e.target.id==='access-form'){e.preventDefault();enterAccess();}if(e.target.id==='next-case-form'){e.preventDefault();enterNextCase();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.record){const r=state.records[el.dataset.record];if(r){r[el.dataset.field]=el.value;persist();const next=$('to-synthesis');if(next)next.disabled=entries().length<2||!entries().every(([,r])=>r.sentence.trim()&&r.reason.trim());}}if(el.id==='final-thought'){state.thought=el.value;if(state.decisionText!==el.value.trim()){state.thoughtDecision=null;const ext=$('extension');if(ext)ext.remove();}persist();}});
document.addEventListener('focusout',e=>{if(e.target.id==='final-thought')thoughtFinished();});
document.addEventListener('keydown',e=>{if(e.target.id==='final-thought'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.blur();thoughtFinished();}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-species-choice]');if(!card)return;draggedSpecies=card.dataset.speciesChoice;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedSpecies);});
document.addEventListener('dragover',e=>{const slot=e.target.closest('[data-rank-slot]');if(!slot||slot.disabled)return;e.preventDefault();e.dataTransfer.dropEffect='move';slot.classList.add('drag-over');});
document.addEventListener('dragleave',e=>{e.target.closest('[data-rank-slot]')?.classList.remove('drag-over');});
document.addEventListener('drop',e=>{const slot=e.target.closest('[data-rank-slot]');if(!slot||slot.disabled)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain')||draggedSpecies;slot.classList.remove('drag-over');if(id)placeSpecies(id,Number(slot.dataset.rankSlot));draggedSpecies='';});
document.addEventListener('dragend',e=>{e.target.closest('[data-species-choice]')?.classList.remove('dragging');document.querySelectorAll('.rank-slot.drag-over').forEach(el=>el.classList.remove('drag-over'));draggedSpecies='';});
$('dialog').addEventListener('cancel',e=>{if(state.page===5&&$('dialog-content').querySelector('[data-action="skip-save"]')){e.preventDefault();chooseSave(false);}});
$('teacher').onclick=teacher;$('restart-page').onclick=restartCurrentPage;$('switch-user').onclick=switchUser;document.querySelector('.brand').onclick=e=>{e.preventDefault();location.href='../diverse-culture/';};render();














